package com.example.onemarket.presentation.profile

import android.graphics.Typeface
import android.os.Bundle
import android.text.SpannableStringBuilder
import android.text.Spanned
import android.text.style.StyleSpan
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import com.example.onemarket.databinding.BottomSheetPrivacyPolicyBinding
import com.google.android.material.bottomsheet.BottomSheetBehavior
import com.google.android.material.bottomsheet.BottomSheetDialog
import com.google.android.material.bottomsheet.BottomSheetDialogFragment

class PrivacyPolicyBottomSheet : BottomSheetDialogFragment() {

    private var _binding: BottomSheetPrivacyPolicyBinding? = null
    private val binding get() = _binding!!

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = BottomSheetPrivacyPolicyBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        (dialog as? BottomSheetDialog)?.behavior?.apply {
            state = BottomSheetBehavior.STATE_EXPANDED
            isDraggable = true
            skipCollapsed = true
        }

        binding.btnClose.setOnClickListener { dismiss() }
        binding.tvPrivacyText.text = buildText()
    }

    private fun buildText(): SpannableStringBuilder {
        val sb = SpannableStringBuilder()

        fun bold(text: String) {
            val s = sb.length
            sb.append(text)
            sb.setSpan(StyleSpan(Typeface.BOLD), s, sb.length, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        }
        fun normal(text: String) { sb.append(text) }

        bold("İSTİFADƏ ŞƏRTLƏRİ\n")
        bold("Bir ID XİDMƏTİ\n")
        bold("Preambula\n")
        normal("Ekosistem iştirakçıları maliyyə texnologiyasının maliyyə əlçatanlığını, səmərəliliyini və yeniliyini artırmaqda transformativ potensialını tanımaqla üstün maliyyə və ödəniş xidmətləri göstərmək və istifadəçi təcrübəsini artırmaq üçün güclü tərəflərindən istifadə edən qarşılıqlı faydalı innovasiya ekosistemini inkişaf etdirməyi öhdələrinə götürürlər;\n\n")

        bold("Ümumi müddəalar\n")
        normal("Ekosistem istifadəçilərin qarşılıqlı əlaqəsi üçün ümumi məkan olduğundan, Ekosistem Xidmətlərindən, vebsaytlardan, veb səhifələr arasında keçidlərdən istifadə edən bütün şəxslər üçün etibarlı olan İstifadəçilərə tanış olan Xidmətlərin istifadəsini yaxşılaşdırmaq məqsədi daşıyan Xidmətlər dizayn edilmişdir. Bu şərtlər Bir ID vasitəsilə xidmətlərdən istifadə edərkən sizinlə Bank, ekosistemin digər iştirakçıları və bütün digər maraqlı tərəflər arasındakı əlaqəni müəyyənləşdirir.\nBu Müqavilə imzalandığı zaman \"biz\", \"bizə\" və \"bizim\" dedikdə, Kapital Bank ASC nəzərdə tutulur.\nBu müqaviləyə Bank tərəfindən birtərəfli qaydada dəyişiklik və/və ya əlavə edilə bilər. Bu Müqavilə açıq və ictimai bir təklifdir. Bu Müqavilənin qüvvədə olan versiyası istifadəçinin şəxsi kabinetində mövcuddur. İstifadəçilərə dəyişiklik və/və ya əlavələr üçün bu müqavilənin şərtlərini mütəmadi olaraq yoxlamağı tövsiyə edirik. Bu Müqaviləyə dəyişikliklər və/və ya əlavələr edildikdən sonra istifadəçi tərəfindən ekosistem xidmətlərindən istifadənin davam etdirilməsi İstifadəçinin bu cür dəyişiklik və/və ya əlavələri qəbul etdiyi və razılaşdığı mənasına gəlir.\nBank, Bir ID xidmətinə ekosistem iştirakçılarına və/və ya istifadəçilərinə giriş və istifadə icazəsi vermək və istənilən vaxt istifadə və/və ya giriş icazələrini birtərəfli qaydada müəyyənləşdirmək, dəyişdirmək, düzəliş etmək, məhdudlaşdırmaq, ləğv etmək və/və ya aradan qaldırmaq üçün bütün lazımi hüquq və səlahiyyətlərə malikdir. Bank, müxtəlif Ekosistem iştirakçıları üçün Bir ID xidmətlərinin verilməsi və/və ya istifadəsi üçün müxtəlif qaydalar tətbiq edə bilər. İstifadəçilərin girişinə və istifadəsinə təsir edən fərqlər müəyyən bir Ekosistem iştirakçısının xidmətlərində istifadəçilər tərəfindən görülə və ya təsdiqlənə bilər.\n\n")

        bold("Terminlər və izahları\n")
        normal("Bank – Azərbaycan qanunvericiliyinə uyğun qeydiyyatdan keçmiş, (VÖEN: 9900003611), hüquqi ünvanı AZ1014, Bakı, Nəsimi rayonu, Füzuli küç., 71-də yerləşən, 244 nömrəli, 05/11/2018 tarixli Bank Lisenziyasına sahib \"Kapital Bank\" Açıq Səhmdar Cəmiyyəti.\nBir ID dedikdə, mobil telefon nömrəsi vasitəsilə Xidmətlərə daxil olmağa imkan verən və bütün məlumatları bir istifadəçi adı altında birləşdirərək qeydiyyatdan keçməyə imkan verən vahid istifadəçi hesabı nəzərdə tutulur.\nEkosistem dedikdə, iştirakçıların əməkdaşlığı və birgə fəaliyyəti əsasında xidmət göstərməklə istifadəçilərin gündəlik ehtiyaclarını ödəməyə yönəlmiş ümumi məqsədləri olan rəqəmsal məkan nəzərdə tutulur. Ekosistem iştirakçılarının siyahısı tam deyil və iş ehtiyaclarına və bazar tələblərinə əsasən dəyişdirilə bilər. Hər hansı bir ekosistem xidmətindən və/və ya alətdən istifadə edən bütün şəxslərə tətbiq olunan, bundan sonra Müqavilə adlandırılacaq bu İstifadə Şərtlərini hazırladıq və yerləşdirdik.\nXidmət(lər) – dedikdə, ilkin olaraq \"Birbank\", \"M10\" və \"Umico Market Place\" tərəfindən yaradılmış, Ekosistem daxilində iştirakçılar tərəfindən təqdim edilən digər proqramlar, mobil tətbiqlər, onlayn mağazalar, onlayn platformalar və ya məhsul veb səhifələri, habelə Bankın əməkdaşlıq etdiyi və/və ya gələcəkdə əməkdaşlıq edəcəyi şirkətlər və məhsullar nəzərdə tutulur;\nİstifadəçi və ya Siz dedikdə, Bir ID ilə qeydiyyatdan keçmiş şəxs nəzərdə tutulur.\nMüqavilə – dedikdə, Bir ID xidmətlərindən istifadə şərtləri nəzərdə tutulur.\n\n")

        bold("Müqavilənin predmeti\n")
        normal("Bu Müqavilənin şərtlərinə uyğun olaraq, Sizə aşağıdakı giriş növlərini, imkanlarını və üstünlüklərini ödənişsiz təqdim edirik:\nBir ID vasitəsilə məlumatlarınızın təhlükəsiz qeydiyyatı və idarə edilməsi;\nSizə və məlumatlarınıza gündəlik olaraq tanış Xidmətlərdən rahat və təhlükəsiz istifadə etməyə imkan verən texniki inteqrasiya yolu ilə Ekosistemə daxil edilmiş funksional alətlər dəsti;\nEkosistemin loyallıq proqramlarında iştirak etmək imkanı;\nBütün Ekosistemdə və onun xidmətlərində fərdi istifadəçi təcrübəsi.\nBir ID-də qeydiyyatdan keçmək Azərbaycan Respublikası Mülki Məcəlləsinin 409-cu maddəsinə uyğun olaraq bu Müqavilənin müddəalarının və müvafiq istifadə şərtlərinin və məxfilik siyasətinin (əvvəllər və bundan sonra Xidmətin İstifadəçi sənədləri adlandırılacaq) qeyd-şərtsiz və ya istisnasız olaraq sizin tərəfinizdən tam qəbul edilməsi deməkdir. Ekosistem iştirakçıları hər hansı bir Xidmət çərçivəsində Bir ID-də qeydiyyatdan keçərsə, onun əhatə dairəsində olan Müqavilənin müddəaları hər hansı Ekosistemin iştirakçısı ilə İstifadəçi arasındakı münasibətlərə şamil ediləcək. Ekosistem iştirakçısı və İstifadəçi arasında bu Müqaviləni aktivləşdirmək üçün İstifadəçi Bir ID vasitəsilə müvafiq Xidmətə daxil olmalıdır.\nİstifadəçi sənədlərinə əsasən xidmətlərin istifadəsini məhdudlaşdıra bilərik.\nXidmətlərin sonrakı sadələşdirilmiş autentifikasiyası və/yaxud qeydiyyatı və/və ya istifadəsi, İstifadəçi məlumatlarının ötürülməsi və bu məlumatların bizim tərəfimizdən alınması üçün lazım olan məlumatları toplayırıq; Beləliklə, Xidmətlərdən istifadə hüquqlarını təmin etmək və/yaxud vermək, eyni zamanda Bir ID yaratmaq və Bir ID ilə Xidmət(lərdə) qeydə alınmış/cari hesab(lar)/qeydiyyatlar arasında sinxronizasiyanı təmin etmək üçün işləyirik.\n\n")

        bold("Bir ID Qeydiyyatı\n")
        normal("İstifadəçi sənədlərinin şərtlərini qəbul etməklə Bir ID-nizi müvafiq veb saytında yarada bilərsiniz.\nBir ID-də qeydiyyatdan keçdikdən sonra avtomatik olaraq xidmətlərə giriş imkanı ilə təmin olunacaqsınız.\nBir ID-nin yaradılması Bankın müəyyən etdiyi prosedura uyğun olaraq ya mobil qurğular, ya da digər elektron vasitələrlə həyata keçirilir.\nBir ID-nin yaradılması ödənişsizdir və qeydiyyat formasını müvafiq veb saytında və ya xidmətlər vasitəsilə doldurmaqla həyata keçirilir.\nİstifadəçi bu Müqaviləni imzalamaqla Azərbaycan Respublikasının qanunvericiliyinə uyğun olaraq icazə verilən yaş həddinə çatdığını təsdiq edir.\nİstifadəçi müəyyən edilmiş yaş həddinə çatmayıbsa və qüvvədə olan qanunun tələb etdiyi hallarda, Xidmətlərdən istifadə yalnız valideynin və ya uşağın hüquqi nümayəndə(lər)inin (bundan sonra Valideyn adlandırılacaq) razılığı ilə mümkündür..\nQeydiyyat zamanı verilən məlumatların düzgünlüyünə, aktuallığına, tamlığına və uyğunluğuna görə məsuliyyət daşıyırsınız.\nQeydiyyatdan keçmək üçün lazım olan məlumatları verdikdən sonra bir sıra yoxlama prosedurlarından keçməlisiniz, yəni kodu müvafiq formaya daxil edərək qeydiyyatı başa çatdırmalısınız.\nQeydiyyat prosesi istifadəçi tərəfindən göstərilən mobil telefon nömrəsinə birdəfəlik şifrənin (\"OTP\") ötürülməsini əhatə edə bilər. Sizə SMS mesajı/buraxılmış zəng/robotdan zəng və ya göstərdiyiniz nömrə ilə mobil telefonunuza göndərdiyimiz avtomatik bildirişlər şəklində OTP və ya digər kod göndəriləcək.\nBütün qeydiyyat mərhələlərinin düzgün ardıcıl icrası halında, Bir ID yaradılacaqdır.\nYuxarıda göstərilənlərə əlavə olaraq, hər hansı bir Xidmətdə Bir ID vasitəsilə İstifadəçini autentifikasiya etməklə və ya İstifadəçi üçün əvvəllər Ekosistemdə hesab yaradılmayıbsa, bu Müqaviləni müstəqil qəbul etməklə Ekosistem hesabı yaratmaq da mümkündür.\nİnteqrasiya edilmiş xidmətlərdən hər hansı biri vasitəsilə birbaşa autentifikasiya ilə Bir ID yarada biləcəksiniz.\nBir ID əvvəllər yaradılmamışsa, Bir ID-nin yaradılması da bu Müqavilənin və digər istifadəçi sənədlərinin ayrıca qəbul edilməsini tələb edir.\nİstifadəçi tərəfindən bu Müqavilənin və İstifadəçi sənədlərinin yerinə yetirilməsi üçün, o cümlədən Xidmətlərin inkişaf etdirilməsi və yenilərinin istifadəyə verilməsi, Xidmətlərin keyfiyyətinin optimallaşdırılması, istifadəçilərə fərdiləşdirilmiş funksiyaları tam həcmdə təqdim etmək məqsədilə Ekosistemin mövcud funksionallığının təkmilləşdirilməsi, Azərbaycan Respublikasının qüvvədə olan şəxsi məlumat qanunvericiliyinə uyğunluq, Xidmətdə qeydiyyat və/və ya autentifikasiya üçün zəruri olan məlumatlar daxil olmaqla, Sizin haqqınızda məlumatların toplanması, ötürülməsi və qəbulu və/və ya Xidmətlərin funksionallığından istifadə, o cümlədən Ekosistemdə hesabın yaradılması və saxlanılması, Xidmətlər tərəfindən bu cür məlumatların sonrakı toplanması, saxlanması, yığılması, sistemləşdirilməsi, çıxarılması, müqayisəsi, istifadəsi, doldurulması, habelə bu cür məlumatların Xidmətlərdən alınması, bu cür məlumatların avtomatlaşdırılmış işlənməsinin nəticələrinin toplanması və emalı, tam ədədlər və/yaxud mətn dəyərləri və bizim tərəfimizdən və/və ya Xidmətlər tərəfindən verilənlərin emalı sorğularında göstərilən qiymətləndirmə meyarlarına uyğun gələn identifikatorlar şəklində məlumatın qiymətləndirilməsi üçün müxtəlif modellərdən istifadə də daxil olmaqla qəbul edir və bizə təlimat verirsiniz.\nŞəxsi məlumatlarınızı icazəsiz giriş, dəyişiklik, açıqlama və ya məhv olmaqdan qorumaq üçün bütün lazımi tədbirləri görürük. Şəxsi məlumatlarınıza yalnız ekosistemin düzgün işləməsini təmin etmək və xidmətlərə və onların funksionallığına giriş təmin etmək üçün bu məlumatlara ehtiyacı olan işçilərə, podratçılara və agentlərə giriş imkanı veririk. Azərbaycan Respublikasının qüvvədə olan qanunvericiliyinin tələblərinə əməl olunmasını təmin etmək, Ekosistem İstifadəçilərinin, Ekosistemin və üçüncü şəxslərin hüquq (qanunsuz hərəkətlərin müəyyən edilməsi, yoxlanılması/araşdırılması və/və ya qarşısının alınması daxil olmaqla) və mənafelərini qorumaq məqsədilə, Ekosistem İstifadəçisi tərəfindən təqdim edilən məlumatlardan, o cümlədən şəxsi məlumatlardan istifadə etmək və bu məlumatları üçüncü tərəflərə ötürmək hüququmuz var. Ekosistem İstifadəçisi tərəfindən verilən məlumatlar yalnız Azərbaycan Respublikasının qüvvədə olan qanunvericiliyinə uyğun olaraq məhkəmənin, hüquq-mühafizə orqanlarının tələbi ilə, habelə Azərbaycan Respublikasının qanunvericiliyi ilə nəzərdə tutulmuş digər hallarda açıqlana bilər.\nHər bir Xidmət Ekosistemdən alınan məlumatları Azərbaycan Respublikasının mövcud qanunvericiliyinə, o cümlədən fərdi məlumatlar haqqında qanunvericiliyə tam uyğun olaraq emal etməyi öhdəsinə götürür və bu öhdəliyə əməl edilmədikdə tam məsuliyyət daşıyır.\nBaşqalarına hesabınıza giriş icazəsi vermək hüququnuz yoxdur. İdentifikasiya üçün tələb olunan məlumatların təhlükəsizliyinə, müstəqil şəkildə saxlanma üsulunu seçməklə təkbaşına məsuliyyət daşıyırsınız. İstifadəçi ekosistemdə və/və ya xidmətdə sonrakı avtomatik avtorizasiya məqsədi ilə İstifadəçinin istifadə etdiyi aparat və proqram təminatında məlumatların saxlanmasına icazə verə bilər.\nBaşqa cür sübut edilmədikdə, ekosistem vasitəsilə həyata keçirilən hər hansı bir fəaliyyət istifadəçi tərəfindən yerinə yetirilmiş hesab olunur. Bir ID hesabına icazəsiz giriş halında, bu faktı müəyyən edilmiş qaydada dərhal bizə bildirməlisiniz.\nBank Bir ID-ə daxil olmaq üçün parol təyin etmək tələbini müəyyən etmək hüququna malikdir. Parol təyin etmə mexanizmi ilə bağlı məlumatlar İstifadəçiyə Bankın və ya ekosistemin müxtəlif kanalları vasitəsilə çatdırılmalıdır.\n\n")

        bold("Kamera, məkan və digər xüsusiyyətlərə giriş\n")
        normal("Bluetooth, məkan, klaviatura kilidi, telefonun vəziyyəti, sistem xəbərdarlıq pəncərəsi, təqvim, kamera, kontaktlar, mikrofon, bildirişlər, sensorlar, SMS mesajları, sosial media hesabları, xarici yaddaş və digər xüsusiyyətlər daxil olmaqla mobil cihazınızın müxtəlif xüsusiyyətlərinə giriş tələb edə bilərik. Sözügedən giriş icazələri aşağıdakılar daxil olmaqla müəyyən məqsədlərə xidmət edir:\nBluetooth - Bir ID vasitəsilə NFC (Near Field Communication) funksiyasından istifadə etmək üçün nəzərdə tutulmuşdur.\nMəkan (yer) - İstifadəçinin koordinatlarını müəyyənləşdirmək, ən yaxın tərəfdaş təşkilatları, bank filiallarını və ya bankomatları axtarmaq, onlayn növbə sistemindən istifadə etmək və digər xidmətlər göstərmək üçündür;\nKlaviatura kilidi - FİN kodunuzu və digər gizli məlumatları qorumaq üçün nəzərdə tutulmuşdur;\nTelefonun vəziyyəti - mobil cihazın kilidli və ya kilidsiz olduğunu müəyyən etmək üçündür;\nSistem xəbərdarlıq pəncərəsi - ekran görüntüsü (skrinşot) yaratmaq funksiyasını aktivləşdirmək və ya deaktivləşdirmək üçündür;\nKamera - kartları, QR kodlarını, şəxsiyyət vəsiqələrini və digər sənədləri oxumaq, QR kodları ilə ödənişlər və digər əməliyyatları icra etmək üçün nəzərdə tutulmuşdur;\nKontaktlar - dostlara ötürmək, qəbzləri bölüşmək, mobil operator xidmətlərindən istifadə etmək (məsələn, balansı artırmaq), həmçinin kodları və ya digər məlumatları üçüncü şəxslərə ötürmək üçündür;\nXarici yaddaş - Ödənişdən sonra qəbzləri saxlamaq, mobil cihazın qalereyasından QR şəkillərini yükləmək və elektron hesab üçün şəkillər seçmək məqsədilə istifadə edilir;\nBloklama mühafizəsi - cihazların ekranlarının qaralmasının və ya kilidlənməsinin qarşısını almaq üçündür;\nAvtomatik bildirişlər - Bir ID haqqında bildirişləri göndərmək üçündür. Bu bildirişləri almamağa üstünlük verirsinizsə, mobil cihazınızın parametrlərində bildiriş funksiyasını söndürə bilərsiniz.\n\n")

        bold("Digər veb saytlara keçidlər:\n")
        normal("Xidmətlər xarici saytlara keçidləri ehtiva edə bilər. Üçüncü tərəfin linkinə klikləsəniz, həmin sayta yönləndiriləcəksiniz. Xahiş edirik unutmayın ki, bu xarici saytlar bizim nəzarətimizdə deyil. Buna görə də, bu müvafiq veb saytların məxfilik siyasətini nəzərdən keçirməyinizi tövsiyə edirik. Üçüncü tərəf saytlarının və ya xidmətlərinin məzmununa, məxfilik siyasətinə və ya tətbiqinə nəzarət etmirik və bununla əlaqədar yarana biləcək problemlərə görə məsuliyyət daşımırıq.\nMövcud qanunvericiliyə uyğun olaraq, məlumatlarınızı marketinq məqsədləri üçün Sizin razılığınızla üçüncü tərəflərə ötürə bilərik. İstənilən vaxt razılığınızı geri götürmək hüququnuz var. Tətbiqin digər istifadəçiləri ilə qarşılıqlı əlaqədə olsanız, onlar adınız, profil şəkliniz, göndərdiyiniz dəvətnamələr, digər istifadəçilərlə əlaqə, bəyənmələr və blog izləmələriniz daxil olmaqla, məlumatlarınıza daxil ola bilərlər.\nBir ID-də istifadə rahatlığını və istifadəçi təcrübəsini artırmaq üçün barmaq izlərindən və ya digər şəxsi biometrik məlumatlardan istifadə etməyə icazə verə bilərik.\nMüxtəlif müsabiqələr, lotereyalar, yarış və sorğular təşkil etmək üçün sadalanan giriş icazələrinin məqsəd və nömrələrini dəyişə və giriş məlumatı tələb edə bilərik. Giriş icazələrinizi dəyişdirmək istəyirsinizsə, bunu mobil cihazınızın parametrlərində icra edə bilərsiniz. Xahiş edirəm unutmayın ki, parametrlərin dəyişdirilməsi və ya giriş icazələrinin dayandırılması/ləğvi ekosistem xidmətlərindən istifadə imkanınızı məhdudlaşdıra bilər.\n\n")

        bold("İstifadəçinin hüquq və vəzifələri\n")
        normal("Xidmətlərdən istifadə zamanı İstifadəçinin vəzifələri aşağıdakılardır:\nAzərbaycan Respublikasının qüvvədə olan qanunvericiliyinin, bu Müqavilənin və qeydiyyatdan keçdiyi xidmətlərin istifadəçi sənədlərinin müddəalarına riayət etmək;\nHesab yaradarkən etibarlı, tam və aktual məlumatları təmin etmək və məlumatları yeni saxlamaq;\nBir ID-ə icazəsiz giriş barədə bizə məlumat vermək;\nAzərbaycan Respublikasının qanunlarını və/və ya bu Müqaviləni və/və ya İstifadəçinin sənədlərini poza bilərsə, başqa şəxslərə onun hesabına və ya orada olan müəyyən məlumatlara çıxış imkanı verməmək;\nİstifadəçi üçün vacib olan və Bir ID və/və ya xidmətlərdə saxlanılan məlumatların ehtiyat nüsxəsini çıxarmaq.\nİstifadəçinin aşağıdakıları icra etməsi qadağandır:\nBaşqa şəxsin adından və ya onun əvəzinə İstifadəçi kimi hesab yaratmaq (\"saxta hesab\");\nŞəxsi məlumatları təhrif etmək;\nProqram təminatından istifadə və Bir ID və/və ya xidmətlərin və ya onun alətlərinin normal fəaliyyətini pozmağa yönəlmiş hərəkətlər etmək;\nVirusları, troyan atlarını və ya digər zərərli proqramları yükləmək, saxlamaq, dərc etmək, yaymaq və ya girişi təmin etmək və ya başqa şəkildə istifadə etmək;\nSaxtakarlıq, etibardan sui-istifadə halları və ya xakerlik daxil olmaqla, lakin bununla məhdudlaşmayaraq, başqalarının giriş məlumatlarına, parollarına və ya fayllarına hər hansı şəkildə daxil olmağa cəhd.\nİstifadəçinin hüquqları aşağıdakılardır:\nİstifadəçinin Bir ID-ni müstəqil silmək hüququ dedikdə, İstifadəçinin Bir ID-də qeydiyyatdan keçdiyi bütün və ya hər hansı Xidmətlərdən və əvvəllər verilmiş bütün hüquqlardan imtina etməsi nəzərdə tutulur; Eyni zamanda, İstifadəçi öz müstəqil mülahizəsinə əsasən Bir ID hesabını bərpa etmək imkanını özündə saxlayır. Bununla belə, Bir ID hesabının bu şəkildə silinməsi İstifadəçinin Ekosistemdəki Xidmətlərdən ayrıca istifadə etmək seçimini aradan qaldırmır;\nİstifadəçinin öz şəxsi kabineti vasitəsilə əvvəllər qeydiyyatdan keçdiyi istənilən Xidməti müstəqil şəkildə dayandırması, yəni İstifadəçinin Bir ID vasitəsilə qeydiyyatdan keçməsindən asılı olmayaraq müvafiq Xidmət(lər)dən istifadəni dayandırması və bu Xidmətdən istifadə ilə bağlı ona əvvəllər verilmiş bütün hüquqlardan imtina etməsi;\nİstifadəçi bu Müqaviləni və ona edilən dəyişiklik və əlavələri qəbul etmədikdə, müvafiq Xidmətlərdə göstərilən addımları yerinə yetirərək qərarı barədə Banka məlumat verərsə, Xidmətlərdən istifadəni dayandırmalıdır.\n\n")

        bold("Bankın hüquq və vəzifələri:\n")
        normal("Bankın cari idarə edilməsini və inkişafını həyata keçiririk, bu Müqavilənin müddəalarının həmin şəxslər tərəfindən pozulması halında İstifadəçilərin Xidmətlərə çıxışına icazə verir və ya məhdudlaşdırırıq və bu Müqaviləyə uyğun olaraq digər hüquqlardan istifadə edirik;\nİstifadəçiyə hər hansı xərc və ya itkini ödəmədən İstifadəçinin Bir ID-ini bloklamaq/silmək və/və ya İstifadəçinin Xidmətlərdən hər hansı birinə girişini dayandırmaq, məhdudlaşdırmaq və ya ləğv etmək hüququmuz var.\nBankın hüquqları aşağıdakılardır:\nEkosistem daxilində əməkdaşlıq etmək üçün istifadəçini lazımi texniki və məlumat dəstəyi ilə məqbul bir müddətdə təmin etmək;\nİstifadəçinin Xidmətlərdən istifadə zamanı qarşılaşdığı problemlər/məsələlər və onların gələcək inkişafı/təkmilləşdirilməsi ilə bağlı İstifadəçidən məlumat/şərhlər əldə etmək üçün birbaşa telefon, elektron poçt və ya digər vasitələrlə (və ya Xidmətlər daxilində təklif olunan digər vasitələrlə) İstifadəçi ilə əlaqə saxlamaq;\nXidmətlərdə texniki xidmət işlərinin aparılması lazım olduğu hallarda, fors-major hallarda, üçüncü tərəfin proqram və aparat sistemlərinin qəzaları və ya nasazlıqları və ya üçüncü şəxslərin Xidmətlərin funksionallığının tam və ya bir hissəsinin dayandırılması və ya dayandırılmasına yönəldilmiş hərəkətləri zamanı Xidmətlərə və alətlərə girişin təmin edilməsini dayandırmaq;\nİstifadəçidən istənilən vaxt Bir ID-də göstərilən məlumatlarını təsdiqləməsini tələb etmək.\nBank məlumatların yoxlanılması məqsədilə təsdiqedici sənədləri (xüsusilə şəxsiyyəti təsdiq edən sənədləri) tələb edə bilər; Bunların təqdim edilməməsi, Bankın mülahizəsinə əsasən, yanlış məlumatların təqdim edilməsi mənasına gələ bilər. İstifadəçinin təqdim etdiyi sənədlərdə göstərilən məlumatlar Bir ID-də göstərilən məlumatlara uyğun gəlmirsə və Bir ID-də göstərilən məlumatlar İstifadəçinin eyniləşdirilməsinə imkan vermirsə, Ekosistem İstifadəçinin Bir ID-ə daxil olmasına və Xidmətlərdən istifadəsinə mane ola bilər.\n\n")

        bold("Təsdiq və Bəyanatlar\n")
        normal("İstifadəçi Bir ID-nin qeydiyyatı və ya istifadəsi zamanı verilən məlumatların tam, dəqiq və istifadəçiyə məxsus olduğunu təsdiqləyir və bəyan edir. Bir ID vasitəsilə aparılan əməliyyatlar zamanı rekvizitlərin, məbləğlərin və ya digər məlumatların səhv daxil edilməsi və İstifadəçiyə aid olmayan məlumatların istifadəsi nəticəsində yarana biləcək risklər İstifadəçiyə məxsusdur.\nBir ID vasitəsilə əməliyyatlar apararkən istifadəçi şəxsi identifikasiya məlumatlarının məxfiliyini və təhlükəsizliyini təmin etmək üçün tədbirlər görməyi, habelə bu Müqavilənin müddəaları pozulduğu və ya mövcud qanunvericiliyə uyğun olaraq qadağan edildiyi təqdirdə üçüncü şəxslərə ötürməməyi öhdəsinə götürür. Bank təhlükəsiz məlumat mübadiləsini təmin etmək üçün tədbirlər görsə də, bu cür məlumatların Bankın nəzarətindən kənar üçüncü şəxslər tərəfindən istifadəsi nəticəsində istifadəçinin və ya üçüncü şəxslərin vurduğu zərərlərə görə məsuliyyət daşımır.\nBank, mobil cihazın və/və ya SİM kartın itirilməsi, oğurlanması və ya hər hansı digər itkisi, habelə üçüncü şəxslərin qanunsuz istifadəsi nəticəsində istifadəçinin vurduğu zərərlərə görə məsuliyyət daşımır.\nİstifadəçi Bir ID vasitəsilə əməliyyatlar və/və ya sənədlərin imzalanması ilə bağlı bütün riskləri öz üzərinə götürür. Buna görə İstifadəçi şərtləri və tarifləri (əgər varsa) diqqətlə oxumalı və yalnız bütün şərtlər aydın başa düşüldükdən sonra əməliyyata başlamalıdır.\nİstifadəçi Bir ID-dən qeyri-qanuni, təhqiredici, ədəbsiz və ya hədələyici məqsədlər və ya qadağan edilmiş və ya məhdudlaşdırılmış mal və xidmətlər, idman mərcləri və ya qumar oyunları ilə bağlı əməliyyatlar üçün istifadə etməməlidir. İstifadəçi hərəkətlərinə və bu cür hallardan irəli gələn nəticələrə görə tam məsuliyyət daşıyır.\nBununla, təhlükəsizlik sistemi üçün lazımi yeniləmələri və ya Bir ID üçün proqram təminatının əlavə qurğularını, əgər varsa və ya tələb olunarsa quraşdırmağı qəbul edirsiniz.\nBir ID istifadə edərək, istifadəçi məlumat xarakterli və reklam mesajlarının alınmasına razılıq verir. İstifadəçi Xidmətin müvafiq funksiyalarından istifadə edərək və ya alınan reklam mesajında göstərilən təlimatlara əməl etməklə reklam mesajlarından imtina edə bilər.\nMobil cihaz və ya əməliyyat sistemi təminatçısı tərəfindən dəstəklənməyən və ya zəmanət verilməyən dəyişdirilmiş bir cihazda və ya əməliyyat sistemində Bir ID istifadə etməməlisiniz. Buraya kilidi açılmış və ya rutlanmış cihazların istifadəsi daxildir.\n\n")

        bold("Bir ID xidmətinin dayandırılması\n")
        normal("Bank İstifadəçinin bu Müqavilənin müddəalarını pozmasına görə məsuliyyət daşımır və öz mülahizəsinə əsasən, həmçinin digər istifadəçilərdən və ya üçüncü şəxslərdən bu Müqavilənin İstifadəçi tərəfindən pozulması barədə məlumat aldıqda, istənilən vaxt, birtərəfli qaydada, əvvəlcədən xəbərdarlıq etməklə və ya etmədən Bir ID-ni qadağan etmək/silmək və/və ya İstifadəçinin hər hansı Xidmətlərə və/və ya alətlərə çıxışını dayandırmaq, məhdudlaşdırmaq və ya ləğv etmək hüququnu özündə saxlayır.\nBank aşağıdakı səbəblərə görə bu hüquqlardan istifadə edə bilər:\nBank İstifadəçinin hərəkətlərində bu Müqavilənin müddəalarının pozulması əlamətləri aşkar etdikdə;\nAzərbaycan Respublikası qanunvericiliyinin bütün tələblərinə əməl olunmaq şərti ilə dövlət hakimiyyəti orqanlarının və məhkəmənin müvafiq tələbi ilə;\nBir ID giriş alətlərinin üçüncü tərəflərə ötürülməsi, təyin edilməsi, satışı, mübadiləsi;\nBir ID haqqında digər istifadəçiləri yanıltmaq;\nXidmətlərə hər hansı müdaxilə və hər hansı bir pozuntu;\nBir ID-dən qanunsuz hərəkətlər etmək üçün istifadə edilməsi.\n\n")

        bold("Zəmanət və Məsuliyyət\n")
        normal("İstifadəçilər bu Müqavilənin şərtlərinə əməl etmək üçün məsuliyyət daşıyırlar.\nEkosistem və onun Xidmətləri və/və ya alətləri \"olduğu kimi\" təmin edilir. Bank, Ekosistemin funksionallığının səhvsiz və problemsiz işləyəcəyinə heç bir zəmanət vermir.\nBank Bir ID-dən hər hansı istifadənin birbaşa və ya dolayı nəticələrinə görə, Azərbaycan Respublikasının qanunlarında açıq şəkildə nəzərdə tutulmuş hallar istisna olmaqla, heç bir məsuliyyət daşımır.\n\"Bir ID\" Bankın ticarət nişanıdır. Bu ticarət nişanı üzrə bütün hüquqlar Banka məxsusdur. İstifadəçilərin şəxsi, təşkilati və ya kommersiya məqsədləri üçün Bankın ticarət nişanlarından, loqosundan və ya brend adından istifadə etməsi qadağandır.\n\n")

        bold("Məxfilik Siyasəti\n")
        normal("Bank təqdim etdiyiniz bütün məlumatların (Şəxsi məlumatlar və digər məxfi məlumatlar daxil olmaqla) məxfiliyini qorumaq üçün tədbirlər görür. Bununla belə, sizin və ya üçüncü şəxslərin bu məlumatdan sizin və ya onların təqsiri üzündən sui-istifadə etməsi nəticəsində İstifadəçiyə və ya üçüncü şəxslərə dəyən hər hansı zərərə görə məsuliyyət daşımırıq.\nBank sizin məxfi məlumatlarınızdan Azərbaycan Respublikasının qanunvericiliyi ilə icazə verilən dərəcədə istifadə edəcək. Bu məlumatları müvafiq məxfilik və təhlükəsizlik standartlarını təmin etməkdən məsul olduqlarından əmin olmaq üçün digər kredit ittifaqları, filiallar, xidmət təminatçıları və ya agentlərlə paylaşa bilərik.\nMəlumatları yalnız Azərbaycan Respublikasının qanunvericiliyi ilə icazə verilən və ya tələb olunan dərəcədə müvafiq icra və ya məhkəmə hakimiyyəti orqanlarına açıqlayacağıq.\nSizin haqqınızda şəxsi məlumatları aşağıdakı məqsədlər üçün toplayırıq:\nBir ID-də qeydiyyatdan keçməklə təqdim olunan funksiyanı aktivləşdirmək;\nEkosistem vasitəsilə təklif olunan xidmətlərin miqyasını genişləndirmək;\nEkosistem vasitəsilə göstərilən xidmətlərin səmərəliliyi və effektivliyini qiymətləndirmək;\nBir ID-də istifadəçi fəaliyyətini təhlil edərək müştəri məmnuniyyətini artırmaq.\nBir ID-dən istifadə edərək, yuxarıda göstərildiyi kimi məlumatların açıqlanmasına, işlənməsinə, saxlanmasına və ötürülməsinə razılıq verirsiniz.\nBu Müqaviləni imzalamaqla, Bankın \"Şəxsi məlumatlar haqqında\" qanuna uyğun olaraq sizin banka təqdim etdiyiniz şəxsi məlumatlarınızı toplaya, emal edə və ötürə biləcəyi ilə razılaşırsınız. Bu Müqavilə sizin Xidmətlərdən istifadə etdiyiniz müddətdə qüvvədə qalır.\n\n")

        bold("Əlavə şərtlər\n")
        normal("Bu Müqavilənin hər hansı bir bəndi qismən və ya tamamilə etibarsız hesab edilərsə, etibarsız bənd digər bəndlərin etibarlılığına xələl gətirmədən bu Müqavilədən silinəcəkdir.\nTərəflər arasında hər cür bildiriş, xəbərdarlıq və s. bu Müqavilədə göstərilən mobil telefon nömrələrinə SMS, sifarişli poçt göndərişi, e-poçt, teleqram və ya faks vasitəsilə göndəriləcəkdir.\nBu Müqavilə ilə hüquqlarımızın hamısını və ya bir hissəsini digər tərəfə ötürmək hüququmuz var. İstifadəçi bu müqavilənin hüquq və vəzifələrini yalnız yazılı razılığımızla başqa bir şəxsə ötürə bilər.\nBu Müqavilə ilə bağlı hər hansı iddia Azərbaycan Respublikasının qanunvericiliyi ilə tənzimlənir.\nBu Müqavilə çərçivəsində tərəflər arasında yarana biləcək hər hansı mübahisə məcburi məhkəməyə qədər icraatdan istifadə etməklə yazışma və danışıqlar yolu ilə həll edilməlidir.")

